    CH_BELL: 164,
}


def vol_col(v):
    v = max(0, min(64, int(v)))
    return 0x10 + v


class ModuleBuilder:
    def __init__(self, name="Keygenesis", channels=12, bpm=140, speed=6):
        self.calls = [
            {"name": "module_new", "arguments": {"channels": channels, "name": name}},
            {"name": "song_set", "arguments": {"bpm": bpm, "speed": speed}},
        ]
        self.channels = channels
        self.patterns_used = set()

    def load_instruments(self, instruments):
        for inst in instruments:
            idx = inst["instrument"]
            self.calls.append({
                "name": "instrument_set",
                "arguments": {"instrument": idx, "name": inst["name"]},
            })
            self.calls.append({
                "name": "sample_create_from_pcm",
                "arguments": {
                    "instrument": idx,
                    "sample": 0,
                    "pcm": inst["pcm_b64"],
                    "encoding": "int16",
                    "name": inst["name"],
                },
            })
            self.calls.append({
                "name": "sample_set",
                "arguments": {
                    "instrument": idx,
                    "sample": 0,
                    "volume": inst["volume"],
                    "panning": inst["panning"],
                    "relative_note": inst["relative_note"],
                    "finetune": inst["finetune"],
                    "loop_start": inst["loop_start"],
                    "loop_length": inst["loop_length"],
                    "flags": inst["flags"],
                },
            })

    def ensure_pattern(self, pat, rows=64):
        if pat not in self.patterns_used:
            self.patterns_used.add(pat)
            self.calls.append({"name": "pattern_set_length", "arguments": {"pattern": pat, "rows": rows}})
            self.calls.append({"name": "pattern_clear", "arguments": {"pattern": pat}})

    def cell(self, pat, row, ch, note=None, inst=None, vol=None, eff=None, param=None):
        self.ensure_pattern(pat)
        args = {"pattern": pat, "row": int(row), "channel": int(ch)}
        if note is not None:
            args["note"] = note
        if inst is not None:
            args["instrument"] = int(inst)
        if vol is not None:
            args["volume"] = vol_col(vol)
        if eff is not None:
            args["effect"] = int(eff)
        if param is not None:
            args["effect_param"] = int(param)
        self.calls.append({"name": "pattern_set_cell", "arguments": args})

    def init_channel_pans(self, pat):
        for ch, pan in CH_PAN.items():
            self.cell(pat, 0, ch, eff=0x08, param=pan)

    def set_order(self, order_list, loop_start=0):
        self.calls.append({"name": "song_set", "arguments": {"length": len(order_list), "loop_start": loop_start}})
        for pos, pat in enumerate(order_list):
            self.calls.append({"name": "order_set", "arguments": {"position": pos, "pattern": pat}})


NOTE_NAMES = ["C-", "C#", "D-", "D#", "E-", "F-", "F#", "G-", "G#", "A-", "A#", "B-"]

def note_to_midi(n):
    if n == "OFF":
        return None
    return int(n[-1]) * 12 + NOTE_NAMES.index(n[:-1])

def midi_to_note(m):
    return f"{NOTE_NAMES[m % 12]}{m // 12}"

def transpose(n, semitones):
    if n is None or n == "OFF":
        return n
    return midi_to_note(note_to_midi(n) + semitones)


CHORD_ARPS = {
    "Em":     ("E-4", 0x37),
    "C":      ("E-4", 0x38),   # E-G-C
    "D":      ("F#4", 0x38),   # F#-A-D
    "B7":     ("D#4", 0x36),   # D#-F#-A
    "Bm":     ("D-4", 0x38),   # D-F#-B
    "Am":     ("E-4", 0x58),   # E-A-C (2nd inv)
    "G":      ("D-4", 0x59),   # D-G-B
    "F#dim":  ("F#4", 0x36),   # F#-A-C
    "E":      ("E-4", 0x47),   # E-G#-B
}


def write_arp_bar(mb, pat, bar_idx, chord_key, vol=38, inst=I_ARP, gate=True, rhythm="16th"):
    r0 = bar_idx * 16
    base, param = CHORD_ARPS[chord_key]
    if rhythm == "16th":
        for i in range(16):
            r = r0 + i
            v = vol if (i % 4 == 0) else int(vol * 0.80)
            if i == 0:
                mb.cell(pat, r, CH_ARP, note=base, inst=inst, vol=v, eff=0x00, param=param)
            elif gate and (i % 4 == 3):
                mb.cell(pat, r, CH_ARP, vol=int(vol * 0.55), eff=0x00, param=param)
            else:
                mb.cell(pat, r, CH_ARP, eff=0x00, param=param)
    elif rhythm == "retrig":
        for i in range(16):
            r = r0 + i
            if i % 4 == 0:
                mb.cell(pat, r, CH_ARP, note=base, inst=inst, vol=vol, eff=0x00, param=param)
            else:
                mb.cell(pat, r, CH_ARP, eff=0x00, param=param)
    elif rhythm == "sync":
        hits = {0, 3, 6, 8, 10, 12, 14}
        for i in range(16):
            r = r0 + i
            if i in hits:
                mb.cell(pat, r, CH_ARP, note=base, inst=inst, vol=vol, eff=0x00, param=param)
            else:
                mb.cell(pat, r, CH_ARP, vol=int(vol * 0.62), eff=0x00, param=param)


def write_pad_bar(mb, pat, bar_idx, note, vol=19, inst=I_PAD):
    r0 = bar_idx * 16
    mb.cell(pat, r0, CH_PAD, note=note, inst=inst, vol=vol)


def write_bass_bar(mb, pat, bar_idx, root, fifth=None, style="electro", vol=44, inst=I_BASS):
    r0 = bar_idx * 16
    oct_hi = transpose(root, 12)
    if fifth is None:
        fifth = transpose(root, 7)

    if style == "electro":
        pat_notes = [
            (0, root, vol),
            (2, oct_hi, int(vol * 0.82)),
            (4, root, int(vol * 0.90)),
            (6, oct_hi, int(vol * 0.86)),
            (8, root, vol),
            (10, oct_hi, int(vol * 0.84)),
            (12, root, int(vol * 0.92)),
            (14, fifth, int(vol * 0.86)),
            (15, oct_hi, int(vol * 0.74)),
        ]
        for off, n, v in pat_notes:
            mb.cell(pat, r0 + off, CH_BASS, note=n, inst=inst, vol=v)
        for off in [1, 5, 9]:
            mb.cell(pat, r0 + off, CH_BASS, vol=int(vol * 0.35))

    elif style == "offbeat_pump":
        for b in range(4):
            rb = r0 + b * 4
            mb.cell(pat, rb + 0, CH_BASS, note=root, inst=inst, vol=int(vol * 0.70))
            mb.cell(pat, rb + 2, CH_BASS, note=oct_hi, inst=inst, vol=vol)
            mb.cell(pat, rb + 3, CH_BASS, note=root, inst=inst, vol=int(vol * 0.62))

    elif style == "rolling16":
        for i in range(16):
            n = oct_hi if (i % 4 == 2) else (fifth if i == 14 else root)
            v = vol if (i % 4 == 0 or i % 4 == 2) else int(vol * 0.68)
            mb.cell(pat, r0 + i, CH_BASS, note=n, inst=inst, vol=v)


def write_drums_bar(mb, pat, bar_idx, style="electro", crash=False, fill=None):
    r0 = bar_idx * 16
    if crash:
        mb.cell(pat, r0, CH_PERC, note="C-4", inst=I_CRASH, vol=44)

    if style == "electro":
        for off in [0, 6, 10]:
            mb.cell(pat, r0 + off, CH_KICK, note="C-4", inst=I_KICK, vol=50)
        for off in [4, 12]:
            mb.cell(pat, r0 + off, CH_SNARE, note="C-4", inst=I_SNARE, vol=54)
        for i in range(16):
            if i in (2, 14):
                mb.cell(pat, r0 + i, CH_HAT, note="C-4", inst=I_HATO, vol=42)
            elif i % 2 == 0:
                mb.cell(pat, r0 + i, CH_HAT, note="C-4", inst=I_HATC, vol=42)
            else:
                mb.cell(pat, r0 + i, CH_HAT, note="C-4", inst=I_HATC, vol=24)

    elif style == "four_floor":
        for off in [0, 4, 8, 12]:
            mb.cell(pat, r0 + off, CH_KICK, note="C-4", inst=I_KICK, vol=52)
        for off in [4, 12]:
            mb.cell(pat, r0 + off, CH_SNARE, note="C-4", inst=I_SNARE, vol=52)
            mb.cell(pat, r0 + off, CH_PERC, note="C-4", inst=I_CLAP, vol=38)
        for i in range(16):
            if i % 4 == 2:
                mb.cell(pat, r0 + i, CH_HAT, note="C-4", inst=I_HATO, vol=44)
            elif i % 2 == 0:
                mb.cell(pat, r0 + i, CH_HAT, note="C-4", inst=I_HATC, vol=42)
            else:
                mb.cell(pat, r0 + i, CH_HAT, note="C-4", inst=I_HATC, vol=26)

    elif style == "intro_pulse":
        for off in [0, 4, 8, 12]:
            mb.cell(pat, r0 + off, CH_KICK, note="C-4", inst=I_KICK, vol=42)
        for i in range(16):
            if i % 4 == 2:
                mb.cell(pat, r0 + i, CH_HAT, note="C-4", inst=I_HATO, vol=34)
            elif i % 2 == 0:
                mb.cell(pat, r0 + i, CH_HAT, note="C-4", inst=I_HATC, vol=32)

    elif style == "breakdown":
        mb.cell(pat, r0 + 0, CH_KICK, note="C-4", inst=I_KICK, vol=40)
        mb.cell(pat, r0 + 10, CH_KICK, note="C-4", inst=I_KICK, vol=34)
        mb.cell(pat, r0 + 12, CH_PERC, note="C-4", inst=I_CLAP, vol=30)
        for i in [0, 4, 8, 12, 14]:
            mb.cell(pat, r0 + i, CH_HAT, note="C-4", inst=I_HATC, vol=28)

    if fill == "snare_tom":
        mb.cell(pat, r0 + 8, CH_PERC, note="G-4", inst=I_TOM, vol=44)
        mb.cell(pat, r0 + 10, CH_PERC, note="D-4", inst=I_TOM, vol=46)
        mb.cell(pat, r0 + 12, CH_SNARE, note="C-4", inst=I_SNARE, vol=54)
        mb.cell(pat, r0 + 13, CH_SNARE, note="C-4", inst=I_SNARE, vol=42)
        mb.cell(pat, r0 + 14, CH_PERC, note="A-3", inst=I_TOM, vol=48)
        mb.cell(pat, r0 + 15, CH_SNARE, note="C-4", inst=I_SNARE, vol=56)
    elif fill == "snare_build":
        for off in [0, 4, 8, 10, 12, 13, 14, 15]:
            v = 32 + off * 2
            mb.cell(pat, r0 + off, CH_SNARE, note="C-4", inst=I_SNARE, vol=min(56, v))
    elif fill == "stop_pickup":
        mb.cell(pat, r0 + 8, CH_KICK, note="C-4", inst=I_KICK, vol=52)
        mb.cell(pat, r0 + 8, CH_PERC, note="C-4", inst=I_CLAP, vol=42)
        mb.cell(pat, r0 + 12, CH_SNARE, note="C-4", inst=I_SNARE, vol=50)
        mb.cell(pat, r0 + 13, CH_PERC, note="G-4", inst=I_TOM, vol=44)
        mb.cell(pat, r0 + 14, CH_PERC, note="D-4", inst=I_TOM, vol=46)
        mb.cell(pat, r0 + 15, CH_SNARE, note="C-4", inst=I_SNARE, vol=56)


def write_lead_phrase(mb, pat, notes_list, inst=I_PULSE, vol=54, ch=CH_LEAD, echo_ch=CH_ECHO,
                      echo_vol=26, vibrato=0x53, cut_end=False):
    occupied_echo = set()
    pan_for_ch = CH_PAN.get(ch, 128)
    for idx, item in enumerate(notes_list):
        r, n, dur = item[0], item[1], item[2]
        extra = item[3] if len(item) > 3 else {}
        v = extra.get("vol", vol)
        eff = extra.get("eff", None)
        param = extra.get("param", None)
        use_inst = extra.get("inst", inst)

        # Enforce channel panning on note trigger when effect slot is free
        if eff is None:
            eff = 0x08
            param = pan_for_ch

        mb.cell(pat, r, ch, note=n, inst=use_inst, vol=v, eff=eff, param=param)
        if dur >= 4 and extra.get("eff", None) is None and vibrato:
            mb.cell(pat, r + 1, ch, eff=0x04, param=vibrato)
            mb.cell(pat, r + 2, ch, eff=0x04, param=vibrato)
            if dur >= 5:
                mb.cell(pat, r + 3, ch, eff=0x04, param=vibrato)

        end_r = r + dur
        next_r = notes_list[idx + 1][0] if idx + 1 < len(notes_list) else 64
        if end_r < next_r and end_r < 64:
            mb.cell(pat, end_r, ch, note="OFF")
        elif cut_end and idx == len(notes_list) - 1 and end_r < 64:
            mb.cell(pat, end_r, ch, note="OFF")

        if echo_ch is not None and dur >= 3:
            er = r + 3
            if er < 61 and er not in occupied_echo:
                mb.cell(pat, er, echo_ch, note=n, inst=use_inst, vol=echo_vol, eff=0x08, param=CH_PAN[echo_ch])
                occupied_echo.add(er)
                if er + 3 < 63:
                    mb.cell(pat, er + 3, echo_ch, note="OFF")


