    # ==================================================================
    p = 0
    mb.init_channel_pans(p)
    for b, ck in enumerate(["Em", "C", "D", "B7"]):
        write_arp_bar(mb, p, b, ck, vol=36 + b * 3, inst=I_ARP)
    for b, pn in enumerate(["E-4", "C-4", "D-4", "B-3"]):
        write_pad_bar(mb, p, b, pn, vol=16 + b * 2)
