    mb.cell(p, 32, CH_SUB, note="D-2", inst=I_SUB, vol=30)
    mb.cell(p, 48, CH_SUB, note="B-1", inst=I_SUB, vol=34)
    mb.cell(p, 63, CH_SUB, note="OFF")

    intro_bells = [
